def _garantir(con) -> None:
    """Cria só as quatro tabelas, se o banco do teste ainda não as tem.

    O schema inteiro do caixa pede `ri_protocolos`. Estes testes não.
    """
    con.execute(
        """CREATE TABLE IF NOT EXISTS cx_vigencias (
               codigo INTEGER PRIMARY KEY,
               descricao TEXT,
               vigente INTEGER NOT NULL DEFAULT 0,
               inicio TEXT,
               fim TEXT)""")
    con.execute(
        """CREATE TABLE IF NOT EXISTS cx_servicos (
               codigo INTEGER PRIMARY KEY,
               codigo_tj TEXT,
               descricao TEXT,
               ativo INTEGER NOT NULL DEFAULT 1)""")
    con.execute(
        """CREATE TABLE IF NOT EXISTS cx_servico_valores (
               id INTEGER PRIMARY KEY AUTOINCREMENT,
               servico INTEGER NOT NULL,
               vigencia INTEGER NOT NULL,
               emolumentos TEXT, ferc TEXT, femp TEXT, fadep TEXT,
               ferrfis TEXT, total TEXT)""")
    con.execute(
        """CREATE TABLE IF NOT EXISTS cx_faixas (
               id INTEGER PRIMARY KEY AUTOINCREMENT,
               tabela INTEGER NOT NULL,
               vigencia INTEGER NOT NULL,
               de TEXT NOT NULL,
               ate TEXT NOT NULL,
               codigo_tj TEXT,
               emolumentos TEXT, ferc TEXT, femp TEXT, fadep TEXT,
               ferrfis TEXT, total TEXT)""")


def carregar(con) -> None:
    """Grava a tabela no banco do teste. Idempotente."""
    _garantir(con)
    for sql in (
            "DELETE FROM cx_faixas",
            "DELETE FROM cx_servico_valores",
            "DELETE FROM cx_servicos",
            "DELETE FROM cx_vigencias",
    ):
        con.execute(sql)
    for codigo, descricao, vigente in VIGENCIAS:
        con.execute(
            "INSERT INTO cx_vigencias(codigo, descricao, vigente, inicio, fim) "
            "VALUES (?,?,?,NULL,NULL)",
            (codigo, descricao, vigente))
    for codigo, tj, descricao in SERVICOS:
        con.execute(
            "INSERT INTO cx_servicos(codigo, codigo_tj, descricao, ativo) "
            "VALUES (?,?,?,1)",
            (codigo, tj, descricao))
    for servico, vigencia, total in VALORES:
        con.execute(
            "INSERT INTO cx_servico_valores(servico, vigencia, emolumentos, "
            "ferc, femp, fadep, ferrfis, total) "
            "VALUES (?,?,?,?,?,?,?,?)",
            (servico, vigencia, total, "0,00", "0,00", "0,00", "0,00", total))
    for vigencia, tabela, de, ate, codigo, total in FAIXAS:
        con.execute(
            "INSERT INTO cx_faixas(tabela, vigencia, de, ate, codigo_tj, "
            "emolumentos, ferc, femp, fadep, ferrfis, total) "
            "VALUES (?,?,?,?,?,?,?,?,?,?,?)",
            (tabela, vigencia, de, ate, codigo, total, "0,00", "0,00",
             "0,00", "0,00", total))
